// The Actor returns new items (type "item") plus one row per feed it could not read (type "error").
return $input.all().map(({ json: r }) => r.type === 'error'
  ? { json: { kind: 'feed error', checkedAt: new Date().toISOString(), feed: r.inputUrl, title: '', link: '', published: '', author: '', matchedKeywords: '', summary: r.error } }
  : { json: {
      kind: 'new item',
      checkedAt: r.firstSeenAt,
      feed: r.feedTitle || r.feedUrl,
      title: r.title,
      link: r.link,
      published: r.published,
      author: r.author || '',
      matchedKeywords: (r.matchedKeywords || []).join(', '),
      summary: r.summary || '',
    } });

const rows = $input.all().map(i => i.json);
const items = rows.filter(r => r.kind === 'new item');
const errors = rows.filter(r => r.kind === 'feed error');
if (!items.length && !errors.length) return [];
const shown = items.slice(0, 15).map(r => `• <${r.link}|${(r.title || r.link).replace(/[<>|]/g, '')}> (${r.feed})${r.matchedKeywords ? ` [${r.matchedKeywords}]` : ''}`);
let text = items.length ? `:newspaper: ${items.length} new item(s)\n${shown.join('\n')}` : '';
if (items.length > 15) text += `\n…and ${items.length - 15} more in the sheet`;
if (errors.length) text += `${text ? '\n' : ''}:warning: ${errors.length} feed(s) could not be read: ${errors.map(e => e.feed).join(', ')}`;
return [{ json: { text } }];
